from typing import List

def check(N: int, M: int, Edges: List[List[int]]) -> bool:
    def is_valid(v, pos, path, graph):
        if v not in graph[path[pos - 1]]:
            return False
        if v in path:
            return False
        return True

    def hamiltonian_util(pos, path, graph):
        if pos == N:
            return True
        for v in range(1, N + 1):
            if is_valid(v, pos, path, graph):
                path[pos] = v
                if hamiltonian_util(pos + 1, path, graph):
                    return True
                path[pos] = -1
        return False

    graph = {i: set() for i in range(1, N + 1)}
    for u, v in Edges:
        graph[u].add(v)
        graph[v].add(u)

    path = [-1] * N
    path[0] = 1
    return hamiltonian_util(1, path, graph)
